  "hs.enclos.gerbera.distract": [["v", `Gerbera. Regarde. C'est brillant.`], ["n", `Véronique fait jouer la cuillère dans la lumière. Gerbera hésite... puis abandonne son poste pour l'examiner de très près.`], ["n", `Elle s'empare de la cuillère et l'emporte. C'est la règle.`], ["b", `Biscotte en profite pour fourrer son nez dans le coin interdit. Il y a là tout un trésor.`]],
  "hs.enclos.gerbera.after": [["n", `Gerbera contemple sa cuillère avec adoration. Elle ne la rendra pas.`]],
  "hs.enclos.tresor.label": `Trésor de Gerbera`,
  "hs.enclos.tresor.look": [["n", `Le trésor de Gerbera : une pince à linge, une clé de cadenas, une barrette, et...`], ["v.focus", `...le collier de Blanchette, avec sa sonnaille. La boucle a été défaite proprement. Le cuir n'est ni arraché ni mâché.`]],
  "hs.enclos.tresor.pro": [["v.focus", `Et ça : une plaquette nasale de lunettes, en silicone, à clip. Pour monture métal, modèle des années 2000.`], ["v.focus", `Usée d'un seul côté : son propriétaire penche la tête.`], ["v.amused", `Quelqu'un louche depuis hier soir.`]],
  "hs.enclos.tournesol.label": `Tournesol`,
  "hs.enclos.tournesol.look": [["n", `Tournesol mâche quelque chose de blanc, avec l'air d'un ruminant qui réfléchit à sa vie.`], ["n", `Du papier. Elle le garde dans sa joue et ne le lâchera pas pour si peu.`]],
  "hs.enclos.tournesol.idea": [["b", `Biscotte regarde Tournesol, puis toi, puis Tournesol. Il a une idée. Elle concerne sûrement la nourriture.`]],
  "hs.enclos.tournesol.trade": [["v", `Tournesol. Une carotte. Fraîche. Contre ce que tu as dans la joue.`], ["n", `Tournesol considère l'offre. Elle recrache une boulette de papier mouillé et croque la carotte.`], ["b", `Biscotte regarde sa carotte disparaître. Il ne s'en remettra jamais.`], ["n", `Véronique déplie la boulette. C'est le bas d'une page de carnet, d'une écriture de médecin :`], ["n", `"...cho : Blanchette gestante, 8 sem. env. Repos conseillé. Transport déconseillé."`]],
  "hs.enclos.tournesol.done": [["n", `Tournesol mâche la fin de la carotte. Elle a l'air satisfaite de la transaction.`]],
